import{_ as a,o as r,c as e,ag as o}from"./chunks/framework.DXGyWiRo.js";const u=JSON.parse('{"title":"Лицензионное соглашение с конечным пользователем (EULA)","description":"","frontmatter":{},"headers":[],"relativePath":"mobile-license.md","filePath":"mobile-license.md","lastUpdated":null}'),i={name:"mobile-license.md"};function l(n,t,d,s,p,h){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="лицензионное-соглашение-с-конечным-пользователем-eula" tabindex="-1">Лицензионное соглашение с конечным пользователем (EULA) <a class="header-anchor" href="#лицензионное-соглашение-с-конечным-пользователем-eula" aria-label="Permalink to &quot;Лицензионное соглашение с конечным пользователем (EULA)&quot;">​</a></h1><h2 id="gosms-client-—-мобильное-приложение-для-android" tabindex="-1">GoSMS Client — мобильное приложение для Android <a class="header-anchor" href="#gosms-client-—-мобильное-приложение-для-android" aria-label="Permalink to &quot;GoSMS Client — мобильное приложение для Android&quot;">​</a></h2><p><strong>Лицензиар:</strong> ИП Ульянов Алексей Владимирович<br> ОГРНИП 321132600016985<br> Email: <a href="mailto:support@gosms.ru" target="_blank" rel="noreferrer">support@gosms.ru</a></p><p><em>Редакция от 21 апреля 2026 г.</em></p><hr><p>Настоящее Лицензионное соглашение с конечным пользователем (далее — <strong>Соглашение</strong>) заключается между <strong>ИП Ульяновым Алексеем Владимировичем</strong> (далее — <strong>Лицензиар</strong>) и физическим или юридическим лицом, устанавливающим и использующим мобильное приложение GoSMS Client (далее — <strong>Лицензиат</strong>), в соответствии с положениями ст. 1286 Гражданского кодекса Российской Федерации.</p><p><strong>Установка или использование приложения означает принятие всех условий настоящего Соглашения.</strong> Если Лицензиат не согласен с условиями — он обязан удалить приложение и прекратить его использование.</p><h2 id="_1-объект-лицензии" tabindex="-1">1. Объект лицензии <a class="header-anchor" href="#_1-объект-лицензии" aria-label="Permalink to &quot;1. Объект лицензии&quot;">​</a></h2><p>1.1. Лицензиар предоставляет Лицензиату <strong>простую (неисключительную) лицензию</strong> на использование мобильного приложения <strong>GoSMS Client</strong> (далее — <strong>Приложение</strong>) на условиях настоящего Соглашения.</p><p>1.2. Приложение предназначено для Android-устройств и позволяет:</p><ul><li>подключать Android-смартфон к сервису GoSMS в качестве устройства-отправителя SMS;</li><li>принимать команды от веб-кабинета или API и выполнять отправку/приём SMS-сообщений через SIM-карту устройства;</li><li>вести локальный журнал сообщений и событий;</li><li>синхронизировать контакты и статусы с веб-кабинетом.</li></ul><p>1.3. Приложение <strong>не является SMS-шлюзом</strong>. Все SMS-сообщения отправляются SIM-картой устройства Лицензиата и оплачиваются в соответствии с тарифным планом мобильного оператора.</p><h2 id="_2-условия-использования" tabindex="-1">2. Условия использования <a class="header-anchor" href="#_2-условия-использования" aria-label="Permalink to &quot;2. Условия использования&quot;">​</a></h2><p>2.1. Лицензиату предоставляется право:</p><ul><li>Устанавливать Приложение на Android-устройства, принадлежащие Лицензиату или находящиеся под его законным контролем.</li><li>Запускать и использовать Приложение в соответствии с его функциональным назначением.</li><li>Создавать резервные копии Приложения для личного использования.</li></ul><p>2.2. <strong>Территория</strong> использования: весь мир.</p><p>2.3. <strong>Срок</strong> действия лицензии: бессрочно, до расторжения в соответствии с разд. 6 настоящего Соглашения.</p><h2 id="_3-ограничения" tabindex="-1">3. Ограничения <a class="header-anchor" href="#_3-ограничения" aria-label="Permalink to &quot;3. Ограничения&quot;">​</a></h2><p>Лицензиату <strong>запрещается</strong>:</p><p>3.1. Декомпилировать, дизассемблировать, реконструировать или иным образом пытаться получить исходный код Приложения (за исключением случаев, прямо разрешённых применимым законодательством).</p><p>3.2. Создавать производные произведения на основе Приложения.</p><p>3.3. Продавать, передавать, сублицензировать, сдавать в аренду, предоставлять в пользование третьим лицам права на использование Приложения.</p><p>3.4. Использовать Приложение для нарушения прав третьих лиц, в том числе прав на неприкосновенность частной жизни и персональные данные.</p><p>3.5. Использовать Приложение в целях, противоречащих законодательству Российской Федерации.</p><p>3.6. Удалять или изменять уведомления об авторских правах и иные правовые уведомления в Приложении.</p><h2 id="_4-обновления" tabindex="-1">4. Обновления <a class="header-anchor" href="#_4-обновления" aria-label="Permalink to &quot;4. Обновления&quot;">​</a></h2><p>4.1. Лицензиар вправе выпускать обновления Приложения. Обновления могут изменять функциональность, требования к устройству и условия использования.</p><p>4.2. Для получения полного функционала рекомендуется устанавливать актуальные версии Приложения. Лицензиар не гарантирует поддержку устаревших версий.</p><p>4.3. Значимые изменения в Соглашении, вызванные обновлениями, доводятся до сведения Лицензиата через уведомление в Приложении или по электронной почте.</p><h2 id="_5-интеллектуальная-собственность" tabindex="-1">5. Интеллектуальная собственность <a class="header-anchor" href="#_5-интеллектуальная-собственность" aria-label="Permalink to &quot;5. Интеллектуальная собственность&quot;">​</a></h2><p>5.1. Приложение и все его компоненты (исходный код, алгоритмы, дизайн, товарные знаки) являются объектами интеллектуальной собственности Лицензиара и охраняются законодательством Российской Федерации.</p><p>5.2. Настоящее Соглашение не предоставляет Лицензиату каких-либо прав на интеллектуальную собственность Лицензиара, кроме прямо указанных.</p><h2 id="_6-расторжение" tabindex="-1">6. Расторжение <a class="header-anchor" href="#_6-расторжение" aria-label="Permalink to &quot;6. Расторжение&quot;">​</a></h2><p>6.1. Соглашение прекращается автоматически в случае нарушения Лицензиатом любого из его условий.</p><p>6.2. Лицензиат вправе расторгнуть Соглашение в любое время, удалив Приложение со всех своих устройств.</p><p>6.3. Лицензиар вправе расторгнуть Соглашение в одностороннем порядке, уведомив Лицензиата за <strong>15 календарных дней</strong>, либо незамедлительно при существенных нарушениях.</p><p>6.4. При расторжении Лицензиат утрачивает право использования Приложения и обязан удалить его со всех устройств.</p><h2 id="_7-отказ-от-гарантии-и-ограничение-ответственности" tabindex="-1">7. Отказ от гарантий и ограничение ответственности <a class="header-anchor" href="#_7-отказ-от-гарантии-и-ограничение-ответственности" aria-label="Permalink to &quot;7. Отказ от гарантий и ограничение ответственности&quot;">​</a></h2><p>7.1. Приложение предоставляется «как есть» (as is). Лицензиар не гарантирует его непрерывную работу, отсутствие ошибок или пригодность для конкретных целей Лицензиата.</p><p>7.2. Лицензиар не несёт ответственности за:</p><ul><li>сбои в работе Android-устройства, операционной системы или мобильного оператора;</li><li>потерю данных вследствие неисправности Приложения или устройства;</li><li>косвенные убытки Лицензиата, связанные с использованием Приложения.</li></ul><p>7.3. Совокупная ответственность Лицензиара ограничена суммами, фактически уплаченными Лицензиатом по договору за последние 3 месяца.</p><h2 id="_8-разрешение-на-использование-разрешении-android" tabindex="-1">8. Разрешение на использование разрешений Android <a class="header-anchor" href="#_8-разрешение-на-использование-разрешении-android" aria-label="Permalink to &quot;8. Разрешение на использование разрешений Android&quot;">​</a></h2><p>8.1. Для корректной работы Приложение запрашивает следующие разрешения Android:</p><table tabindex="0"><thead><tr><th>Разрешение</th><th>Назначение</th></tr></thead><tbody><tr><td>SEND_SMS</td><td>Отправка SMS-сообщений</td></tr><tr><td>READ_SMS</td><td>Чтение входящих SMS</td></tr><tr><td>RECEIVE_SMS</td><td>Получение уведомлений о входящих SMS</td></tr><tr><td>READ_CONTACTS</td><td>Синхронизация контактов</td></tr><tr><td>READ_PHONE_STATE</td><td>Определение статуса SIM-карты</td></tr><tr><td>FOREGROUND_SERVICE</td><td>Работа в фоновом режиме</td></tr><tr><td>INTERNET</td><td>Связь с сервером GoSMS</td></tr></tbody></table><p>8.2. Лицензиат может управлять разрешениями в настройках Android. Отключение обязательных разрешений может ограничить функциональность Приложения.</p><h2 id="_9-конфиденциальность" tabindex="-1">9. Конфиденциальность <a class="header-anchor" href="#_9-конфиденциальность" aria-label="Permalink to &quot;9. Конфиденциальность&quot;">​</a></h2><p>9.1. Обработка персональных данных в рамках использования Приложения осуществляется в соответствии с <a href="/privacy-policy">Политикой конфиденциальности</a>.</p><h2 id="_10-применимое-право" tabindex="-1">10. Применимое право <a class="header-anchor" href="#_10-применимое-право" aria-label="Permalink to &quot;10. Применимое право&quot;">​</a></h2><p>10.1. Соглашение регулируется законодательством Российской Федерации.</p><p>10.2. Споры разрешаются путём переговоров, при недостижении соглашения — в судебном порядке по месту нахождения Лицензиара.</p><h2 id="_11-реквизиты-лицензиара" tabindex="-1">11. Реквизиты Лицензиара <a class="header-anchor" href="#_11-реквизиты-лицензиара" aria-label="Permalink to &quot;11. Реквизиты Лицензиара&quot;">​</a></h2><p><strong>ИП Ульянов Алексей Владимирович</strong><br> ОГРНИП 321132600016985<br> Email: <a href="mailto:support@gosms.ru" target="_blank" rel="noreferrer">support@gosms.ru</a><br> Сайт: <a href="https://gosms.ru" target="_blank" rel="noreferrer">https://gosms.ru</a></p>',53)])])}const c=a(i,[["render",l]]);export{u as __pageData,c as default};
